const q="?item=B";const child=document.querySelector('iframe').contentDocument;child.documentElement.innerHTML="\u003c!doctype html>\u003chtml>\u003chead>\u003cmeta charset=\"utf-8\">\u003ctitle>正文子文档\u003c/title>\u003cscript>const install=()=>{document.querySelector('[contenteditable]').oninput=e=>{parent.fetch('/rt-input?item=B',{method:'POST',body:JSON.stringify({value:e.target.innerText,html:e.target.innerHTML,inputType:e.inputType})});}};if(document.readyState==='loading')addEventListener('DOMContentLoaded',install,{once:true});else install();\u003c/script>\u003c/head>\u003cbody>\u003cdiv contenteditable=\"true\" style=\"white-space:pre-wrap;min-height:100px;border:1px solid #888\">\u003c/div>\u003c/body>\u003c/html>";const script=child.createElement('script');script.textContent=child.querySelector('script').textContent;child.head.append(script);
const editor=()=>document.querySelector('iframe').contentDocument.querySelector('[contenteditable]');

document.querySelector('[type=file]').onchange=async e=>{document.querySelector('#upload').textContent='正在上传附件';await fetch('/rt-upload'+q,{method:'POST',body:await e.target.files[0].arrayBuffer()});document.querySelector('#upload').innerHTML='附件已上传 <a href="/rt-file'+q+'">下载附件</a>';};
document.querySelector('#draft').onclick=async()=>{await fetch('/rt-draft'+q,{method:'POST'});document.querySelector('#drafted').textContent='草稿已保存';};
document.querySelector('#destination').onchange=()=>{document.querySelector('#selected').textContent='栏目已填写';};
document.querySelector('#publish').onclick=async()=>{document.querySelector('#result').textContent='正在发布附件';await fetch('/rt-publish'+q,{method:'POST',body:JSON.stringify({heading:document.querySelector('#heading').value,body:editor().innerText,destination:document.querySelector('#destination').value})});document.querySelector('#result').textContent='已正式发布';};

